import { useState } from "react";
export default function Toggle() {
  const [open, setOpen] = useState(false);
  return <button onClick={() => setOpen(value => !value)}>{open ? "Hide" : "Show"}</button>;
}

import { useMemo, useState } from "react";
export default function SearchList() {
  const [query, setQuery] = useState("");
  const courses = ["HTML", "CSS", "Python"];
  const filtered = useMemo(() => courses.filter(c => c.toLowerCase().includes(query.toLowerCase())), [query]);
  return <><input value={query} onChange={e => setQuery(e.target.value)} /><p>{filtered.join(", ")}</p></>;
}

import { useEffect, useState } from "react";
export default function ClockLabel() {
  const [ready, setReady] = useState(false);
  useEffect(() => { setReady(true); }, []);
  return <p>{ready ? "Mounted" : "Starting"}</p>;
}

import { useState } from "react";
export default function Score() {
  const [score, setScore] = useState(0);
  const addFive = () => setScore(s => s + 5);
  return <button onClick={addFive}>Score {score}</button>;
}
